___CSS_LOADER_EXPORT___.push([module.id, `.filter-menu {
  background: white;
  border-radius: 5px;
  z-index: 100;
}
.filter-menu .filter-toggle {
  background: linear-gradient(180deg, #b5c3e3 0%, #dbdeff 40%, #f0f4ff 100%);
  border-radius: 5px;
  border: 1px solid #DDD;
  display: block;
  padding: 5px 10px;
  margin: 6px auto 0px auto;
  cursor: pointer;
  text-align: left;
  font-family: 'Franklin Gothic Medium', 'Arial Narrow', Arial, sans-serif;
  font-weight: 400;
  color: #063a6e;
}
.filter-menu .filter-toggle:hover {
  background: #CCC;
}
.filter-menu #js-toggle-show-all,
.filter-menu #js-toggle-hide-all {
  font-size: 12px;
  padding: 3px 6px;
  font-weight: 500;
}
.filter-menu .filter-toggle-row {
  display: flex;
  gap: 3px;
  margin-top: 6px;
}
.filter-menu #js-filter-toggle {
  width: 100%;
  font-size: 14px;
}
.filter-menu .filter-content {
  display: none;
  border-radius: 0 0 5px 5px;
  padding: 6px 9px;
  border-top: none;
  border-bottom: 1px solid #DDD;
  border-left: 1px solid #DDD;
  border-right: 1px solid #DDD;
  min-width: 150px;
}
.filter-menu .filter-content.open {
  display: block;
}
.filter-menu .filter-content label {
  display: block;
  margin-bottom: 3px;
  cursor: pointer;
  font-size: 12px;
}
.filter-menu .filter-content label input {
  margin-right: 6px;
  cursor: pointer;
}
.filter-menu .filter-content label:hover {
  background: #F5F5F5;
}
.filtered-hidden-explicit {
  opacity: 0.8 !important;
  filter: grayscale(100%);
}
.filtered-hidden-implicit {
  display: none !important;
  pointer-events: none;
}
.rationale-color {
  display: inline-block;
  width: 14px;
  height: 14px;
  margin-right: 6px;
  border-radius: 3px;
}
.rationale-color-best-practice {
  background: #44AA99;
}
.rationale-color-business-rule {
  background: #88CCEE;
}
.rationale-color-norm-or-law {
  background: #AA4499;
}
.rationale-color-law-of-nature {
  background: #EFD036;
}
.rationale-color-not-assigned {
  background: #000000;
}
.implicit-icon {
  width: 14px;
  height: 14px;
  display: inline-block;
  background-image: url(${___CSS_LOADER_URL_REPLACEMENT_0___});
  background-size: 14px 14px;
  filter: none;
  margin-right: 6px;
}
