___CSS_LOADER_EXPORT___.push([module.id, `.properties-panel-parent {
  position: absolute;
  top: 1px;
  bottom: 1px;
  right: 0;
  width: 260px;
  z-index: 10;
  border-left: 1px solid #ccd4e0;
  background: linear-gradient(180deg, #f0f4ff 0%, #f0f4ff 100%);
  border-radius: 8px 0 0 8px;
  overflow: auto;
  box-shadow: -2px 0 8px rgba(74, 144, 226, 0.15);
}
.properties-panel-parent:empty {
  display: none;
}
.properties-panel-parent > .djs-properties-panel {
  padding-bottom: 70px;
  min-height: 100%;
  background: linear-gradient(135deg, #f0f4ff 0%, #f0f4ff 100%);
}
.properties-panel-parent .bio-properties-panel-group {
  border-radius: 12px;
  margin: 16px 12px;
  background: linear-gradient(180deg, #e6f7ff 0%, #f0f4ff 100%);
  box-shadow: 0px 2px 8px rgba(74, 144, 226, 0.08);
  border: 1px solid #a2d9ff;
}
.properties-panel-parent .bio-properties-panel-group-header {
  border-radius: 12px 12px;
  background: linear-gradient(180deg, #b5c3e3 0%, #dbdeff 45%, #f0f4ff 100%);
  color: #205081;
  font-size: 16px;
  font-family: 'Franklin Gothic Medium', 'Arial Narrow', Arial, sans-serif;
  font-weight: bold;
}
.properties-panel-parent .bio-properties-panel-header {
  background: linear-gradient(180deg, #b5c3e3 0%, #dbdeff 40%, #f0f4ff 100%);
  color: #205081;
  font-size: 16px;
  font-weight: bold;
  border-bottom: 0px;
  padding: 18px 16px;
}
