  box-sizing: border-box;
}
body,
html {
  font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;
  font-size: 12px;
  height: 100%;
  max-height: 100%;
  padding: 0;
  margin: 0;
}
a:link {
  font-weight: bold;
  text-decoration: none;
}
p {
  font-size: 14px;
}
.content {
  position: relative;
  width: 100%;
  height: 100%;
}
.content > .message {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  font-size: 16px;
  color: #111;
}
.content > .message .title {
  text-align: center;
  display: block;
  font-size: 34px;
  font-weight: normal;
  font-family: Impact, Haettenschweiler, 'Arial Narrow Bold', sans-serif;
  color: #052d55;
}
.content > .message .note {
  text-align: center;
  display: block;
}
.content > .message .error .details {
  max-width: 500px;
  font-size: 12px;
  margin: 20px auto;
  text-align: left;
}
.content > .message .error pre {
  border: solid 1px #CCC;
  background: #EEE;
  padding: 10px;
}
.content:not(.with-error) .error,
.content.with-error .intro,
.content.with-diagram .message {
  display: none;
}
.content .canvas {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
}
.content .canvas,
.content.with-error .canvas {
  visibility: hidden;
}
.content.with-diagram .canvas {
  visibility: visible;
}
.content .djs-context-pad {
  z-index: 0 !important;
}
.content .properties-panel-parent {
  visibility: hidden;
}
.content.with-diagram .properties-panel-parent {
  visibility: visible;
}
.content.with-diagram .all-buttons-parent {
  visibility: visible;
}
.all-buttons-parent {
  visibility: hidden;
}
.buttons-right {
  position: fixed;
  bottom: 20px;
  right: 300px;
  padding: 0;
  margin: 0;
  list-style: none;
}
.buttons-right > li {
  display: inline-block;
  margin-right: 10px;
}
.buttons-left {
  position: absolute;
  bottom: 20px;
  left: 20px;
  padding: 0;
  margin: 0;
  list-style: none;
}
.buttons-left > li {
  display: inline-block;
}
.buttons-left > li > a {
  width: 34px;
  height: 34px;
  margin-left: 5px;
  background: linear-gradient(180deg, #b5c3e3 0%, #dbdeff 40%, #f0f4ff 100%);
  border: solid 1px #DDD;
  display: inline-block;
  padding: 5px;
  border-radius: 5px;
  color: #063a6e;
}
.buttons-left > li i {
  font-size: 18px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding-top: 3px;
}
.buttons-left #js-download-diagram,
.buttons-left #js-download-svg {
  opacity: 0.3;
  pointer-events: none;
  cursor: default;
}
.buttons-left #js-download-diagram.active,
.buttons-left #js-download-svg.active {
  opacity: 1;
  pointer-events: auto;
  cursor: pointer;
}
.buttons-left a:hover {
  background: #CCC;
}
.without-properties-panel .buttons-right {
  left: auto;
  right: 100px;
}
.implicit-arrow-icon {
  width: 24px;
  height: 24px;
  display: inline-block;
  background-image: url(${___CSS_LOADER_URL_REPLACEMENT_0___});
  background-size: 24px 24px;
  filter: none ;
}
.djs-palette {
  background: linear-gradient(130deg, #b5c3e3 0%, #dbdeff 45%, #e9ebfc 70%, #f0f4ff 100%);
  border-radius: 8px;
  box-shadow: 0 2px 8px rgba(74, 144, 226, 0.15);
}
.djs-palette .entry {
  color: #00274d;
}
