import { DropdownButton } from '../../../components/templates/DropdownButton';
import { html } from 'htm/preact';
import { useService } from 'bpmn-js-properties-panel';
import '../../../style/dropdownStyle.less';

// Dropdown entry that allows the user to select a risk likelihood for an activity relationship
// The selected risk likelihood is saved as a property in the bpmn xml file

export default function(element) {

  return [
    {
      id: 'risk_likelihood',
      element,
      component: RiskLikelihood,
    }
  ];
}

function RiskLikelihood(props){

  const { element} = props;
  const modeling = useService('modeling');

  //Get the currently assigned risk likelihood
  const currentRiskLikelihood = element.businessObject?.risk_likelihood || 'Select a risk likelihood';
  //Define the items for the dropdown menu
  // 'entry' is the displayed text, but 'risk_likelihood' is the actual value of the property saved in the bpmn xml file
  const menuItems = [
     {
      entry: 'Very high risk',
      action: () => modeling.updateProperties(element, { risk_likelihood: 'very_high_risk'})
    },
    {
      entry: 'High risk',
      action: () => modeling.updateProperties(element, { risk_likelihood: 'high_risk'})
    },
    {
      entry: 'Moderate risk',
      action: () => modeling.updateProperties(element, { risk_likelihood: 'moderate_risk'})
    },
    {
      entry: 'Low risk',
      action: () => modeling.updateProperties(element, { risk_likelihood: 'low_risk'})
    },
    {
      entry: 'Not specified',
      action: () => modeling.updateProperties(element, { risk_likelihood: 'not_specified'})
    }
  ]

  //Return the dropdown button with the selected value and menu items
   return html`<${DropdownButton}
    selectedValue=${mapRiskLikelihoodToEntry(currentRiskLikelihood)}
    menuItems=${menuItems}
    className=${'custom-dropdown'}
  />`;
}

//Helper function to display the correct text in the dropdown button for the currently selected risk likelihood
function mapRiskLikelihoodToEntry(riskLikelihood) {
  switch (riskLikelihood) {
    case 'very_high_risk':
      return 'Very high risk';
    case 'high_risk':
      return 'High risk';
    case 'moderate_risk':
      return 'Moderate risk';
    case 'low_risk':
      return 'Low risk';
      case 'not_specified':
        return 'Not specified';
    default:
      return 'Select the risk likelihood';
  }
}